WITH recent_payments AS (SELECT *, SUBSTRING(status, 1, 4) AS status_prefix FROM payments WHERE order_id IS NOT NULL AND paid_at < '2024-01-01' AND amount BETWEEN 1040 AND 1180), order_id_summary AS (SELECT order_id, DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, ROUND((100 * SUM(CASE WHEN status = 'REFUNDED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_refunded, MAX(amount) AS max_amount FROM recent_payments GROUP BY order_id, DATE_FORMAT(paid_at, 'yyyy-MM')) SELECT order_id, paid_month, pct_refunded, max_amount FROM order_id_summary WHERE max_amount >= 1090;
